package com.bank.risk.service;

import java.util.Arrays;
import java.util.logging.Logger;

// Squares a sorted P&L array (with negatives) into a new sorted array.
public class PnlSquarer {
    private static final Logger log = Logger.getLogger(PnlSquarer.class.getName());

    public long[] sortedSquares(int[] pnl) {
        if (pnl == null || pnl.length == 0) return new long[0];
        int n = pnl.length;
        long[] result = new long[n];
        int left = 0;
        int right = n - 1;
        int pos = n - 1; // fill from the back

        while (left <= right) {
            long leftSq = (long) pnl[left] * pnl[left];
            long rightSq = (long) pnl[right] * pnl[right];
            if (leftSq > rightSq) {
                result[pos] = leftSq; // bigger magnitude on the left
                left++;
            } else {
                result[pos] = rightSq;
                right--;
            }
            pos--;
        }
        log.info(() -> "Sorted squares = " + Arrays.toString(result));
        return result;
    }
}
