package com.bank.risk;

import com.bank.risk.service.PnlSquarer;
import java.util.Arrays;
import java.util.logging.Logger;

public class PnlSquarerDemo {
    private static final Logger log = Logger.getLogger(PnlSquarerDemo.class.getName());

    public static void main(String[] args) {
        // Sorted daily P&L: losses negative, profits positive.
        int[] pnl = {-7, -3, 2, 5, 8};
        log.info(() -> "Input P&L: " + Arrays.toString(pnl));

        PnlSquarer squarer = new PnlSquarer();
        long[] squares = squarer.sortedSquares(pnl);

        log.info(() -> "Volatility magnitudes: " + Arrays.toString(squares));
    }
}
